<?php
class Reporte_rentabilidad_viaje extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_rentabilidad_viaje_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_rentabilidad_viaje_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'ruta_id'=>(int)$this->input->get('ruta_id',true),'viaje_id'=>(int)$this->input->get('viaje_id',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['rutas']=$this->Reporte_rentabilidad_viaje_model->rutas();$data['viajes']=$this->Reporte_rentabilidad_viaje_model->viajes($f);$data['filas']=$this->Reporte_rentabilidad_viaje_model->reporte($f);$data['puede_costos']=$this->Reporte_rentabilidad_viaje_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],223);$data['page_title']='Rentabilidad del viaje';$data['_view']='reporte_transporte/rentabilidad_viaje';$this->load->view('layouts/main',$data);}
 public function costos($viaje_id=0){header('Content-Type: application/json; charset=utf-8');echo json_encode($this->Reporte_rentabilidad_viaje_model->costos((int)$viaje_id));}
 public function guardar_costo(){if(!$this->Reporte_rentabilidad_viaje_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],223))show_error('No autorizado',403);$cat=strtoupper(trim((string)$this->input->post('categoria',true)));if(!in_array($cat,array('COMBUSTIBLE','PEAJES','CONDUCTOR','AYUDANTE','OTROS')))show_error('Categoría inválida',400);$viaje=(int)$this->input->post('viaje_id',true);$monto=(float)$this->input->post('monto',true);if($viaje<=0||$monto<=0)show_error('Viaje o monto inválido',400);$this->Reporte_rentabilidad_viaje_model->guardar_costo(array('egreso_numero'=>$this->Reporte_rentabilidad_viaje_model->siguiente_numero(),'usuario_id'=>(int)$this->session_data['usuario_id'],'viaje_id'=>$viaje,'egreso_categoria'=>$cat,'egreso_nombre'=>'COSTO DE VIAJE','egreso_monto'=>$monto,'egreso_moneda'=>'Bs','egreso_concepto'=>trim((string)$this->input->post('concepto',true)),'egreso_fecha'=>date('Y-m-d H:i:s'),'egreso_tc'=>1));redirect($this->input->server('HTTP_REFERER')?:'reporte_rentabilidad_viaje');}
 public function desvincular_costo($id=0){if(!$this->Reporte_rentabilidad_viaje_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],223))show_error('No autorizado',403);$this->Reporte_rentabilidad_viaje_model->desvincular_costo((int)$id);redirect($this->input->server('HTTP_REFERER')?:'reporte_rentabilidad_viaje');}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_rentabilidad_viaje_model->reporte($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="rentabilidad_viajes_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Viaje','Ruta','Fecha','Hora','Pasajes','Encomiendas','Equipaje','Ingresos','Combustible','Peajes','Conductor','Ayudante','Otros costos','Costo','Utilidad estimada','Margen %'),';');foreach($rs as $r){$ing=$r['ingresos_pasajes']+$r['ingresos_encomiendas']+$r['ingresos_equipajes'];$cos=$r['combustible']+$r['peajes']+$r['conductor']+$r['ayudante']+$r['otros_costos'];$ut=$ing-$cos;$mg=$ing>0?$ut*100/$ing:0;fputcsv($x,array($r['viaje_id'],$r['ruta'],$r['fecha'],$r['hora'],$r['ingresos_pasajes'],$r['ingresos_encomiendas'],$r['ingresos_equipajes'],$ing,$r['combustible'],$r['peajes'],$r['conductor'],$r['ayudante'],$r['otros_costos'],$cos,$ut,$mg),';');}fclose($x);exit;}
}
